import test from 'node:test';import assert from 'node:assert/strict';import {ITEMS,NEW_ITEMS,SPECIES,BESTIARY,buyItem,chapterTreasure,applySupply} from '../repertoire.js?v=5.6.0';import {Battle,encounterEnemies} from '../battle.js?v=5.6.0';import {defaultHero} from '../mako.js';
test('new species reach encounters without replacing chapter-one training or story bosses',()=>{const seen=new Set();for(let c=2;c<=24;c++)for(const e of encounterEnemies(c,false,4)){seen.add(e.species);assert.ok(['bestiary','bestiary2'].includes(e.atlas));assert.ok(e.sprite>=0&&e.sprite<12);assert.ok(['guard','scout','mender','predator'].includes(e.role));}assert.equal(seen.size,48);assert.ok(encounterEnemies(1).every(e=>!e.species));assert.ok(encounterEnemies(5,true)[0].boss);assert.equal(new Set(SPECIES.map(s=>s.sprite)).size,12);assert.equal(BESTIARY.length,48);});
test('every new supply has a unique chapter treasure and guarded purchase',()=>{assert.equal(NEW_ITEMS.length,42);assert.equal(new Set(Array.from({length:24},(_,i)=>chapterTreasure(i+1).id)).size,24);const s={items:{tonic:0},chapter:1,gold:100};assert.equal(buyItem(s,'starEther'),false);assert.equal(buyItem(s,'mossWrap',-1),false);assert.equal(s.gold,100);assert.ok(buyItem(s,'mossWrap',2));assert.equal(s.items.mossWrap,2);assert.equal(s.gold,60);});
test('all 45 consumables apply a real effect and spend exactly one ready turn',()=>{for(const item of ITEMS){const a=defaultHero(0,10),b=defaultHero(1,10),dead=defaultHero(2,10);for(const h of [a,b,dead]){h.atb=1;h.status={burn:6,shock:6,slow:6};h.strain=90;h.hp=Math.round(h.maxHp*.4);h.mp=0;}dead.hp=0;const enemies=encounterEnemies(3,false,2);enemies.forEach((e,i)=>{e.x=4+i;e.y=4;e.intent={left:2,total:2};e.status.guard=5;});const battle=new Battle({heroes:[a,b,dead],enemies});a.atb=1;a.strain=90;a.status.burn=6;const inventory={[item.id]:2};assert.ok(applySupply(battle,inventory,item.id,a,enemies[0]),item.id);assert.equal(inventory[item.id],1,item.id);assert.equal(a.atb,0,item.id);assert.equal(applySupply(battle,inventory,item.id,a,enemies[0]),false,item.id);assert.equal(inventory[item.id],1);}});
test('ineffective healing consumes neither item nor actor turn',()=>{const a=defaultHero(0),battle=new Battle({heroes:[a],enemies:encounterEnemies(1)});a.atb=1;const inv={tonic:1};assert.equal(applySupply(battle,inv,'tonic',a,battle.enemies[0]),false);assert.equal(inv.tonic,1);assert.equal(a.atb,1);});
test('special moves retain visible geometry and only apply status on actual hits',()=>{const a=defaultHero(0,10);a.x=100;a.y=100;const e=encounterEnemies(3,false,2)[1];e.x=1;e.y=1;e.turn=1;const b=new Battle({heroes:[a],enemies:[e]});b.planEnemy(e);assert.ok(['burst','line'].includes(e.intent.shape));const intent={...e.intent,x:1,y:1};b.executeIntent(e,intent);assert.equal(a.status[e.moveStatus],undefined);a.x=1;a.y=1;b.executeIntent(e,intent);assert.ok(a.status[e.moveStatus]>0);});
